def calculator(a, b, op):
    if op == "+":
        return a + b
    elif op == "-":
        return a - b
    elif op == "*":
        return a * b
    else:
        return a / b
print("result:", calculator(10, 5, "+"))

def weekly_pay(rate, hour):
    if hour > 30:
        money = rate * 30 + 1.5 * rate * (hour - 30)
    else:
        money = rate * hour
    return money
print(int(weekly_pay(11000, 32)))

def factorial(a):
    result = 1
    for i in range(1, a + 1):
        result *= i
    return result
print(factorial(5))

